package com.scms.backend.scheduling;
import java.time.*; import java.util.*; import com.scms.backend.account.*; import com.scms.backend.audit.*; import com.scms.backend.auth.InvalidAuthenticatedAccountException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service class AttendanceService { final ClassSessionRepository sessions;final BookingRepository bookings;final AttendanceRepository attendance;final AuditEventRepository audits;final AccountRepository accounts;final Clock clock;
 AttendanceService(ClassSessionRepository s,BookingRepository b,AttendanceRepository a,AuditEventRepository au,AccountRepository ac,Clock c){sessions=s;bookings=b;attendance=a;audits=au;accounts=ac;clock=c;}
 @Transactional List<AttendanceResponse> list(UUID coach,UUID sid){ClassSession s=owned(coach,sid);Instant now=clock.instant();if(now.isBefore(s.getStartTime()))throw AttendanceException.closed();for(var m:bookings.findBookedAttendanceMembers(sid))if(m.getAttendanceId()==null)attendance.save(new Attendance(UUID.randomUUID(),m.getBookingId(),m.getMemberId(),AttendanceStatus.ABSENT,now,null,null,"SYSTEM"));return bookings.findBookedAttendanceMembers(sid).stream().map(m->attendance.findByBookingId(m.getBookingId()).map(a->AttendanceResponse.from(a,m)).orElseThrow()).toList();}
 @Transactional AttendanceResponse update(UUID coach,UUID sid,UUID aid,AttendanceUpdateRequest req){ClassSession s=owned(coach,sid);Instant now=clock.instant();if(req==null||req.status()==null)throw AttendanceException.invalid();if(now.isBefore(s.getStartTime())||now.isAfter(s.getEndTime().plusSeconds(1800)))throw AttendanceException.closed();Attendance a=attendance.findById(aid).orElseThrow(AttendanceException::missing);var members=bookings.findBookedAttendanceMembers(sid);if(members.stream().noneMatch(m->aid.equals(m.getAttendanceId())))throw AttendanceException.missing();UUID visit=null;if(req.status()==AttendanceStatus.PRESENT)visit=attendance.findCurrentCenterVisit(a.getMemberId(),s.getStartTime(),now).orElseThrow(AttendanceException::visit);AttendanceStatus before=a.getStatus();a.mark(req.status(),visit,coach,now);attendance.save(a);audits.save(new AuditEvent(UUID.randomUUID(),coach,"ATTENDANCE_CHANGED","Attendance",aid,"Coach changed attendance",Map.of("status",before.name()),Map.of("status",req.status().name())));var m=members.stream().filter(x->aid.equals(x.getAttendanceId())).findFirst().orElseThrow();return AttendanceResponse.from(a,m);}
 private ClassSession owned(UUID coach,UUID sid){if(!accounts.existsByIdAndRoleAndStatus(coach,AccountRole.COACH,AccountStatus.ACTIVE))throw new InvalidAuthenticatedAccountException();return sessions.findByIdAndTeachingCoach_Id(sid,coach).orElseThrow(AttendanceException::missing);}}
